const LanguageContext = createContext(null)
const SUPPORTED_LANGUAGES = ['uz', 'tr', 'en']
const LANGUAGE_STORAGE_KEY = 'turkuaz-edu-lang'

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(() => {
    try {
      const saved = window.localStorage.getItem(LANGUAGE_STORAGE_KEY)
      return SUPPORTED_LANGUAGES.includes(saved) ? saved : 'uz'
    } catch {
      return 'uz'
    }
  })

  useEffect(() => {
    try { window.localStorage.setItem(LANGUAGE_STORAGE_KEY, language) } catch { /* continue in memory */ }
  }, [language])

  const t = useCallback((key, values = {}) => {
    const template = translations[language]?.[key] ?? translations.uz[key] ?? key
    return template.replace(/\{([^}]+)\}/gu, (_, name) => String(values[name] ?? `{${name}}`))
  }, [language])

  const value = useMemo(() => ({ language, setLanguage, t }), [language, t])
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>
}

export function useI18n() {
  const context = useContext(LanguageContext)
  if (!context) throw new Error('useI18n must be used within LanguageProvider')
  return context
}
